		  await sleep(80);
		  await type("[550C] 节点 01-47：COMMAND_ACK.result = MAV_RESULT_ACCEPTED。", "ok");
		  await type("[550C] 所有电机已 disarm。", "ok");
		  await type("[550C] 动力系统紧急关闭完成。", "ok");
		  await type("[550C] 所有无人机进入安全锁定状态。", "ok");
		  mainLine("");
		  await type("[550C] 基站日志写入完成。", "sys");
